// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    PENNY_BY_PENNY c;
    function setUp() public { c = new PENNY_BY_PENNY(); }
    function testFuzz_property(uint256 newMin) public {

        c.SetLogFile(address(0));
        c.Initialized();

        bool ok;
        try c.SetMinSum(newMin) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(!ok);
    }
}
